let cameraViewSequence=0,cameraNeedsUserGesture=false,ocrRunSequence=0,activeOcrController=null,ocrResult=null,processedPreviewUrl=null,photoView='original',ocrErrorMessage='',ocrProgress={status:'Preparando imagen',progress:null},parserResult=null,scanChoices=[],scanReview=null,noteEditing=false;
let adminOcrReport=buildAdminOcrDiagnostic(null,{stage:'file'}),adminOcrImage=null,adminOcrRun=0,adminOcrController=null,adminOcrReports=[],adminOcrPassStates={};
