async function exportValidation(){const secrets=await collectValidationSecrets();const report=createValidationExport({checklist:validationChecklist,environment:validationEnvironment(),secrets});const blob=new Blob([JSON.stringify(report,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`wifi-connect-validacion-${new Date().toISOString().replace(/[:.]/g,'-')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Informe técnico exportado.');}
async function copyValidationReport(){const secrets=await collectValidationSecrets();const text=createReadableReport({checklist:validationChecklist,environment:validationEnvironment(),secrets});try{await navigator.clipboard.writeText(text);toast('Informe copiado.');}catch{toast('No se pudo copiar. Comprueba el permiso del portapapeles.');}}
function updateValidationField(field){const id=field.dataset.validation,key=field.dataset.key;if(!id||!key)return;try{validationChecklist=updateChecklistEntry(validationChecklist,id,{[key]:field.value});saveChecklist(validationChecklist);const detail=root.querySelector(`[data-failure-details="${CSS.escape(id)}"]`);if(detail&&(key==='status'))detail.open=field.value==='fail'||field.value==='partial';const all=Object.values(validationChecklist);const summary=root.querySelector('.validation-summary');if(summary)summary.innerHTML=`<span>🟢 ${all.filter(x=>x.status==='ok').length}</span><span>🟡 ${all.filter(x=>x.status==='partial').length}</span><span>🔴 ${all.filter(x=>x.status==='fail').length}</span><span>⚪ ${all.filter(x=>x.status==='untested').length}</span>`;}catch(error){console.error('[WiFi Connect validation]',error);toast('No se pudo guardar este resultado local.');}}
function savePrompt(){if(current.type==='saved'){toast('Esta red ya está guardada.');return;}ask({title:'Guardar red',body:'Esta red pasará a Guardadas y dejará de caducar.',placeholder:'Ej. Casa cliente - salón',value:current.note||'',confirm:'Guardar',onConfirm:async note=>{const candidate={...current,note:note.trim()};if(candidate.note!==current.note){current=candidate;await storage.saveNetwork(current);}let result=await storage.promoteRecentToSaved(current.id);if(result.conflict){if(!window.confirm(`Ya existe una red guardada con el mismo SSID y seguridad, pero con otra contraseña. ¿Sustituir las credenciales guardadas por las revisadas de ${current.ssid}?`))return;result=await storage.promoteRecentToSaved(current.id,{replaceExisting:true});}if(!result.network){toast('La red reciente ha caducado.');route='recent';await render();return;}if(candidate.note!==result.network.note){result.network={...result.network,note:candidate.note};await storage.savePermanentNetwork(result.network);}current=result.network;networkTab='saved';toast('Red movida a Guardadas.');await render();}});}
async function copyScanDiagnostics(){try{const text=sessionStorage.getItem('wifi-connect-scan-diagnostics');if(!text)throw new Error('No diagnostic');await copyTextToClipboard(text);toast('Diagnóstico copiado sin credenciales.');}catch{toast('No se pudo copiar el diagnóstico.');}}
async function clickAction(action,button){if(action==='validation-export'){await exportValidation();return;}if(action==='validation-copy'){await copyValidationReport();return;}if(action==='validation-scan-copy'){await copyScanDiagnostics();return;}if(action==='validation-scan-clear'){sessionStorage.removeItem('wifi-connect-scan-diagnostics');await render();toast('Diagnóstico eliminado de esta sesión.');return;}if(action==='validation-reset'){if(window.confirm('Restablecer todas las pruebas a “Sin probar” y borrar las notas locales?')){validationChecklist=createChecklist();saveChecklist(validationChecklist);await render();}return;}if(action==='validation-exit'){route='home';await render();return;}if(action==='lab-export'){labExport();return;}if(action==='lab-copy'){labCopy();return;}if(action==='exit-camera'){camera.stop();camera.discardReview();go('home');return;}if(action==='capture'){button.disabled=true;try{await camera.capture();if(LAB_MODE){route='image-review';await render();}else{camera.confirmImage();await beginOcr();}}catch(error){persistScanDiagnostics({stage:'capture-failed',camera:{source:'Cámara',permission:'concedido al abrir'},errorCode:'CAMERA_CAPTURE',durationMs:0,review:{requested:true,reason:'No se pudo capturar la fotografía',fields:[]}});toast(error.message||'No se pudo capturar la foto.');const b=root.querySelector('#capture-button');if(b)b.disabled=false;}return;}if(action==='repeat-photo'){if(['parser-review','ocr-result','ocr-error','band-choice','scan-review','ssid-diagnostics'].includes(route)){clearOcrResult();scanChoices=[];scanReview=null;camera.clearConfirmedImage();route='camera';await render();}else{camera.discardReview();go('camera');}return;}if(action==='confirm-photo'){try{if(!camera.getConfirmedImage())camera.confirmImage();await beginOcr();}catch(error){toast(error.message);}return;}if(action==='cancel-ocr'){cancelOcr();return;}if(action==='repeat-ocr'){await beginOcr();return;}if(action==='detect-wifi-data'){await detectWifiData();return;}if(action==='back-to-ocr'){route='ocr-result';await render();return;}if(action==='manual-from-ocr'){clearOcrResult();camera.clearConfirmedImage();go('manual');return;}if(action==='toggle-parser-secret'){showSecret=!showSecret;const input=root.querySelector('#parser-password');if(input)input.type=showSecret?'text':'password';button.textContent=showSecret?'Ocultar':'Mostrar';return;}if(action==='show-original'){photoView='original';render();return;}if(action==='show-processed'){if(processedPreviewUrl){photoView='processed';render();}return;}if(action==='copy-ocr-text'){const text=root.querySelector('#ocr-editable-text')?.value||'';try{await navigator.clipboard.writeText(text);toast('Texto copiado.');}catch{toast('No se pudo copiar el texto. Puedes seleccionarlo manualmente.');}return;}if(action==='change-photo'){clearOcrResult();camera.clearConfirmedImage();route='camera';await render();return;}if(action==='camera-home'){camera.stop();camera.clearConfirmedImage();camera.discardReview();go('home');return;}if(action==='retry-camera'){cameraNeedsUserGesture=false;route='camera';await render();return;}if(action==='toggle-torch'){const enabled=await camera.toggleTorch();button.classList.toggle('torch-on',enabled);button.textContent=enabled?'⚡ Flash activado':'⚡ Flash';if(!enabled)toast('El flash no está disponible en esta cámara.');return;}if(action==='toggle-secret'){showSecret=!showSecret;const i=shadowRoot.querySelector('#password-input');i.type=showSecret?'text':'password';button.textContent=showSecret?'Ocultar':'Mostrar';return;}if(action==='paste'){await pasteClipboardText({clipboard:navigator.clipboard,target:root.querySelector('#password-input'),onSuccess:()=>toast('Contraseña pegada'),onFailure:()=>toast('No se pudo leer el portapapeles. Mantén pulsado y pega manualmente.')});return;}if(action==='iphone-help'){ask({title:'Copiar la contraseña en iPhone',body:'1. Abre Ajustes.<br>2. Entra en Wi-Fi.<br>3. Pulsa el botón de información de tu red.<br>4. Pulsa Contraseña.<br>5. Identifícate con Face ID o código.<br>6. Copia la contraseña.<br>7. Vuelve a WiFi Connect y pégala.',confirm:'Entendido',onConfirm:()=>{}});return;}if(action==='toggle-result-secret'||action==='toggle-detail-secret'){showSecret=!showSecret;render();return;}if(action==='copy-data'){if(current.type==='recent')current=await storage.touchRecentNetwork(current.id);const details=['SSID: '+current.ssid,'Contraseña: '+(current.password||'Sin contraseña'),'Seguridad: '+current.security].join(String.fromCharCode(10));try{await copyTextToClipboard(details);toast('Datos copiados.');}catch{toast('No se pudieron copiar los datos. Mantén pulsado para copiar.');}return;}if(action==='copy-password'){if(!current?.password){toast('Esta red no tiene contraseña.');return;}if(current.type==='recent')current=await storage.touchRecentNetwork(current.id);try{await copyTextToClipboard(current.password);if(route==='detail')await render();toast('Contraseña copiada');}catch{toast('No se pudo copiar; selecciona la contraseña para copiarla.');}return;}if(action==='share'){if(current?.type==='recent')current=await storage.touchRecentNetwork(current.id);toast(await shareNetwork(current,root.querySelector('svg')));return;}if(action==='save'){if(current?.source==='router_scan'&&current.type==='recent'){await promoteScannedNetwork();return;}savePrompt();return;}if(action==='another'){qrReturnRoute='home';go('home');return;}if(action==='regenerate'){if(current?.type==='recent')current=await storage.touchRecentNetwork(current.id);qrReturnRoute='detail';route='qr';render();return;}if(action==='back-qr'){route=qrReturnRoute==='detail'?'detail':'home';await render();return;}if(action==='detected-home'){route=detailReturnRoute==='recent'?'recent':'home';await render();return;}if(action==='copy-ssid'){try{await copyTextToClipboard(current.ssid);toast('SSID copiado.');}catch{toast('No se pudo copiar el SSID.');}return;}if(action==='edit'){route='manual';await render();return;}if(action==='edit-note'){ask({title:'Editar nota',body:'Añade una referencia para identificar esta red.',placeholder:'Ej. Casa cliente - salón',value:current.note||'',confirm:'Guardar nota',onConfirm:async note=>{current.note=note.trim();current.updatedAt=new Date().toISOString();await storage.saveNetwork(current);toast('Nota actualizada.');route='detail';await render();}});return;}if(action==='delete'){ask({title:'Eliminar esta red',body:'Se borrarán el SSID, la contraseña y la nota guardados. Esta acción no se puede deshacer.',confirm:'Eliminar',danger:true,onConfirm:async()=>{await storage.deleteNetwork(current.id);current=null;route='recent';await render();toast('Red eliminada.');}});return;}if(action==='clear-recents'||action==='clear-saved'){const recentList=action==='clear-recents',label=recentList?'recientes':'guardadas';ask({title:`Borrar redes ${label}`,body:`Se eliminarán únicamente las redes ${label} de este dispositivo. Esta acción no se puede deshacer.`,confirm:`Borrar ${label}`,danger:true,onConfirm:async()=>{if(recentList)await storage.clearRecentNetworks();else await storage.clearSavedNetworks();current=null;await render();toast(`Redes ${label} borradas.`);}});return;}}
root.addEventListener('click',async e=>{const action=e.target.closest('[data-action]');if(action){if(action.dataset.action==='admin-ocr-open'){if(!ADMIN_OCR_DIAGNOSTICS)return;openAdminOcr();return;}if(action.dataset.action==='admin-ocr-back'){if(adminOcrController)cancelAdminOcr();adminOcrImage=null;adminOcrReports=[];route='home';await render();return;}if(action.dataset.action==='admin-ocr-load-reports'){await loadAdminOcrPhotoChoices();return;}if(action.dataset.action==='admin-ocr-use-report'){await useAdminOcrReportPhoto();return;}if(action.dataset.action==='admin-ocr-run'){await runAdminOcr();return;}if(action.dataset.action==='admin-ocr-cancel'){cancelAdminOcr();return;}if(action.dataset.action==='admin-ocr-copy'){try{await copyTextToClipboard(serializeAdminOcrDiagnostic(adminOcrReport));toast('Informe técnico sanitizado copiado.');}catch{toast('No se pudo validar o copiar el informe.');}return;}if(action.dataset.action==='ssid-diagnostic-copy'){if(!SSID_DIAGNOSTIC_MODE)return;try{await copyTextToClipboard(serializeSafeSsidReport(ssidDiagnosticReport));toast('Informe SSID sanitizado copiado.');}catch{toast('No se pudo validar o copiar el informe SSID.');}return;}if(action.dataset.action==='ssid-diagnostic-finish'){if(!SSID_DIAGNOSTIC_MODE)return;ssidDiagnosticReport=null;camera.clearConfirmedImage();clearOcrResult();route='home';await render();return;}if(action.dataset.action==='ssid-diagnostic-repeat'){if(!SSID_DIAGNOSTIC_MODE)return;ssidDiagnosticReport=null;clickAction('repeat-photo',action);return;}if(action.dataset.action==='wifi-report-back'){reportNavigation.close();return;}if(action.dataset.action==='wifi-report-remove-photo'){setWifiReportPhoto(null);reportStatus='';void render();return;}clickAction(action.dataset.action,action);return;}const goButton=e.target.closest('[data-go]');if(goButton){if(goButton.dataset.networkTab){networkTab=goButton.dataset.networkTab;route='recent';current=null;showSecret=false;render();return;}go(goButton.dataset.go);return;}const tab=e.target.closest('[data-network-tab]');if(tab){networkTab=tab.dataset.networkTab;route='recent';render();return;}const open=e.target.closest('[data-open]');if(open){detailReturnRoute=open.dataset.detailReturn==='home'?'home':'recent';current={id:open.dataset.open};route='detail';render();return;}});
root.addEventListener('input',e=>{if(route!=='wifi-report')return;if(e.target.name==='description')reportForm.description=e.target.value;});
root.addEventListener('change',e=>{if(route!=='wifi-report')return;if(e.target.name==='problem')reportForm.problem=e.target.value;if(e.target.name==='photoConsent')reportForm.photoConsent=e.target.checked;if(e.target.name==='shareSsid')reportForm.shareSsid=e.target.checked;if(e.target.name==='photo'){const file=e.target.files?.[0]||null;if(file&&(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size<16||file.size>5*1024*1024)){reportStatus='Elige una fotografía PNG, JPG o WebP de 5 MB como máximo.';void render();return;}setWifiReportPhoto(file);reportStatus='';void render();}});
root.addEventListener('click',e=>{const choice=e.target.closest('[data-scan-choice]');if(choice){const candidate=scanChoices[Number(choice.dataset.scanChoice)];if(candidate)selectScanChoice(candidate);return;}});
shadowRoot.querySelector('.bottom-nav').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b)go(b.dataset.tab==='scan'?'scan':b.dataset.tab);});
root.addEventListener('change',async e=>{if(e.target.id==='detected-note'&&current){current.note=e.target.value.trim();current.updatedAt=new Date().toISOString();await storage.saveNetwork(current);toast('Nota guardada.');}});root.addEventListener('input',e=>{const validation=e.target.closest('[data-validation]');if(validation)updateValidationField(validation);if(e.target.closest('[data-lab]'))updateLabComparison();});root.addEventListener('change',e=>{const validation=e.target.closest('[data-validation]');if(validation)updateValidationField(validation);if(e.target.closest('[data-lab]'))updateLabComparison();});
root.addEventListener('change',e=>{const choice=e.target.closest('[data-parser-choice]');if(!choice)return;const ssidField=choice.dataset.parserChoice==='ssid';const candidates=ssidField?parserResult?.ssidCandidates:parserResult?.passwordCandidates;const candidate=candidates?.filter(c=>(ssidField?isSafeSsidCandidate(c):isSafePasswordCandidate(c))&&c.score>=40).slice(0,5)[Number(choice.value)];const input=root.querySelector(ssidField?'#parser-ssid':'#parser-password');if(input&&candidate)input.value=ssidField?candidateValue(candidate):candidate.value;});
root.addEventListener('change',e=>{if(!e.target.matches('[data-admin-ocr-file]'))return;const file=e.target.files?.[0]||null;if(!file)return;const code=validateAdminOcrFile(file);if(code){adminOcrImage=null;adminOcrReport=buildAdminOcrDiagnostic(null,{stage:'file',failureCode:code,image:{type:file.type||'unknown',sizeBytes:file.size,decode:'not_attempted'}});e.target.value='';void renderAdminOcrSafely(adminOcrRun);toast(code==='FILE_SIZE'?'La imagen debe ocupar entre 16 bytes y 20 MB.':'Selecciona un archivo de imagen compatible.');return;}adminOcrImage=file;adminOcrPassStates={};adminOcrReport=buildAdminOcrDiagnostic(null,{stage:'file',image:{type:file.type||'unknown',sizeBytes:file.size,decode:'not_attempted'}});void renderAdminOcrSafely(adminOcrRun);toast('Fotografía seleccionada; permanece en memoria local.');});
root.addEventListener('change',async e=>{if(e.target.id!=='gallery-input')return;const file=e.target.files?.[0];e.target.value='';if(!file)return;try{await camera.selectImage(file);if(LAB_MODE){route='image-review';await render();}else{camera.confirmImage();await beginOcr();}}catch(error){toast(error.message||'No se pudo abrir esta imagen.');}});
root.addEventListener('submit',async e=>{if(e.target.id==='wifi-report-form'){e.preventDefault();if(reportSubmitting)return;const data=new FormData(e.target);reportForm.problem=String(data.get('problem')||'other');reportForm.description=String(data.get('description')||'');reportForm.photoConsent=data.has('photoConsent');reportForm.shareSsid=data.has('shareSsid');await sendWifiReport(data);return;}if(e.target.id==='scan-review-form'){e.preventDefault();const data=new FormData(e.target),network={...scanReview.network,ssid:String(data.get('ssidReview')??scanReview.network.ssid).trim(),password:String(data.get('passwordReview')??scanReview.network.password)};await saveScannedNetwork(network);return;}if(e.target.id==='parser-review-form'){e.preventDefault();const data=new FormData(e.target);const ssid=String(data.get('ssid')||'').trim(),password=String(data.get('password')||''),security=String(data.get('security')||'WPA/WPA2');const existing=await storage.getAllNetworks(),matchingSaved=existing.find(item=>item.type==='saved'&&item.ssid===ssid&&item.security===security),matchingRecent=existing.find(item=>item.type==='recent'&&item.ssid===ssid&&item.security===security),net={ssid,password,security,hidden:false,note:current?.type==='recent'&&current.ssid===ssid?current.note||'':matchingRecent?.note||matchingSaved?.note||'',origin:'router_scan',source:'router_scan'};const error=validateNetwork(net);if(error){toast(error);return;}if(matchingSaved&&matchingSaved.password!==password){const scanned=await storage.saveRecentNetwork(net);current=scanned;const useSaved=window.confirm('Ya existe una red guardada con el mismo SSID y seguridad, pero con otra contraseña. ¿Usar las credenciales ya guardadas?\nAceptar: mantener Guardada.\nCancelar: conservar la red escaneada como Reciente.');if(useSaved){await storage.deleteNetwork(scanned.id);current=matchingSaved;}}else current=await storage.saveRecentNetwork(net);if(LAB_MODE)readLabFields();showSecret=false;qrReturnRoute='detail';route='detail';await render();return;}if(e.target.id!=='network-form')return;e.preventDefault();const form=e.target,data=new FormData(form);const net={ssid:String(data.get('ssid')||'').trim(),password:String(data.get('password')||''),security:String(data.get('security')||'WPA/WPA2'),hidden:data.has('hidden'),note:String(data.get('note')||'').trim(),origin:form.dataset.origin};const error=validateNetwork(net);if(error){toast(error);return;}const editing=form.dataset.editing==='true'?current:null;if(editing?.type==='saved')current=await storage.savePermanentNetwork({...editing,...net});else current=await storage.saveRecentNetwork({...editing,...net});showSecret=false;route='qr';await render();});
const onVisibilityChange=()=>{if(document.hidden){if(route==='camera'){cameraViewSequence++;camera.stop();cameraNeedsUserGesture=true;}}else if(cameraNeedsUserGesture&&route==='camera'&&shadowRoot.host.isConnected&&shadowRoot.host.getClientRects().length)showCameraPausedScreen();};
const onPageHide=()=>{if(route==='camera'){cameraNeedsUserGesture=true;cameraViewSequence++;}camera.stop();};
const onPageShow=()=>{if(cameraNeedsUserGesture&&route==='camera'&&shadowRoot.host.isConnected&&shadowRoot.host.getClientRects().length)showCameraPausedScreen();};
const onWifiReportPopState=()=>{reportNavigation.handlePopState();};
document.addEventListener('visibilitychange',onVisibilityChange);
window.addEventListener('pagehide',onPageHide);
window.addEventListener('pageshow',onPageShow);
window.addEventListener('popstate',onWifiReportPopState);
try{await storage.cleanupExpiredRecents();await render();}
catch{root.innerHTML='<div class="card">No se pudo iniciar el almacenamiento local.</div>';}
return {
  suspend(){cameraViewSequence++;ocrRunSequence++;activeOcrController?.abort();activeOcrController=null;disposeRouterImageAnalysis();camera.stop();if(['camera','ocr-progress','image-review','image-prepared'].includes(route)){camera.clearConfirmedImage();clearOcrResult();route='home';shell.classList.remove('camera-mode');}},
  resume(){if(route==='home')void render();},
  dispose(){cameraViewSequence++;ocrRunSequence++;activeOcrController?.abort();activeOcrController=null;disposeRouterImageAnalysis();adminOcrRun++;adminOcrController?.abort();adminOcrController=null;adminOcrImage=null;adminOcrReports=[];camera.stop();camera.clearConfirmedImage();clearOcrResult();current=null;parserResult=null;scanReview=null;if(reportPhotoUrl)URL.revokeObjectURL(reportPhotoUrl);try{if(modal.open)modal.close();}catch{}document.removeEventListener('visibilitychange',onVisibilityChange);window.removeEventListener('pagehide',onPageHide);window.removeEventListener('pageshow',onPageShow);window.removeEventListener('popstate',onWifiReportPopState);shadowRoot.replaceChildren();storage.closeStorage();}
};
